import{_ as e,o as r,c as t,a3 as o}from"./chunks/framework.Wx1CEKvH.js";const u=JSON.parse('{"title":"隐私政策","description":"苍蓝星图鉴应用与网站的隐私政策，说明本地数据、设备备份、联系邮件、数据删除和联系方式。","frontmatter":{"description":"苍蓝星图鉴应用与网站的隐私政策，说明本地数据、设备备份、联系邮件、数据删除和联系方式。","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hans/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hans/privacy/"}],["meta",{"property":"og:title","content":"隐私政策 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"苍蓝星图鉴应用与网站的隐私政策，说明本地数据、设备备份、联系邮件、数据删除和联系方式。"}]]},"headers":[],"relativePath":"zh-hans/privacy/index.md","filePath":"zh-hans/privacy/index.md"}'),i={name:"zh-hans/privacy/index.md"};function n(l,a,h,p,s,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p>生效及更新日期：2026 年 10 月 31 日</p><p>这份政策适用于苍蓝星图鉴（Sapphire Star Codex）的 iOS、Android、鸿蒙版应用，以及本网站。开发者是 <strong>eurekaffeine（刘耀晨）</strong>。有隐私方面的问题，可以发邮件到 <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>。</p><p>应用还在开发中，各平台的功能有所不同。下面说明的是当前应用和网站的数据处理方式。使用应用不需要注册账号。</p><h2 id="哪些数据保存在设备上" tabindex="-1">哪些数据保存在设备上？ <a class="header-anchor" href="#哪些数据保存在设备上" aria-label="Permalink to &quot;哪些数据保存在设备上？&quot;">​</a></h2><p>为了记住你的选择、提供相应功能，应用会在设备上保存一些数据。具体取决于你使用的平台和功能，包括：</p><ul><li>选中的游戏、语言、外观等设置。</li><li>搜索记录，以及方便下次接着看的页面状态。</li><li>收藏的怪物、装备等资料。</li><li>保存的配装、自定义配装名称、装饰品数量、护石和防具库存。</li></ul><p>这些数据用于查资料、搜索、收藏和配装。应用不会把它们上传给开发者，也没有由我们运营的账号或云同步服务。</p><h2 id="会申请权限或自动收集信息吗" tabindex="-1">会申请权限或自动收集信息吗？ <a class="header-anchor" href="#会申请权限或自动收集信息吗" aria-label="Permalink to &quot;会申请权限或自动收集信息吗？&quot;">​</a></h2><p>当前应用没有加入广告、追踪、使用统计或自动上传崩溃报告的 SDK。现有功能不需要读取通讯录、定位、相机、麦克风或相册，也不收集广告标识符。</p><p>设备系统和应用商店可能会根据各自的设置与政策，单独处理安装或诊断信息。如果平台向我们提供诊断信息，我们会用它来排查应用问题。</p><h2 id="发邮件时会提供哪些信息" tabindex="-1">发邮件时会提供哪些信息？ <a class="header-anchor" href="#发邮件时会提供哪些信息" aria-label="Permalink to &quot;发邮件时会提供哪些信息？&quot;">​</a></h2><p>你给我们发邮件时，我们会收到你的邮箱地址、邮件内容，以及你主动附上的文件。我们只用这些信息回复你、排查问题和处理隐私请求。请尽量只提供处理问题所需的内容。我们不会把联系记录用于广告或营销邮件。</p><h2 id="网站、备份和其他服务" tabindex="-1">网站、备份和其他服务 <a class="header-anchor" href="#网站、备份和其他服务" aria-label="Permalink to &quot;网站、备份和其他服务&quot;">​</a></h2><p><strong>本网站。</strong> 网站由 GitHub Pages 托管。我们没有添加访问统计、广告 Cookie 或追踪像素。站内搜索在你的浏览器里完成，显示和搜索偏好也可能保存在浏览器中。访问网站时，GitHub 会收到 IP 地址、浏览器信息等技术请求信息，具体处理方式见 <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub 隐私声明</a>。</p><p><strong>设备备份。</strong> 根据你的系统设置，应用数据可能被包含在设备备份或云备份中。这些备份由相应的平台服务商管理，我们无法替你读取或删除。</p><p><strong>邮件和外部链接。</strong> 我们使用 Gmail 接收邮件，Google 会按照 <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google 隐私政策</a>处理邮件服务所需的信息。打开外部网站或应用商店后，适用的是对方的隐私政策。网站托管、邮件和备份服务商可能在你所在国家或地区以外处理信息。</p><h2 id="数据会分享给谁-保留多久-怎么删除" tabindex="-1">数据会分享给谁，保留多久，怎么删除？ <a class="header-anchor" href="#数据会分享给谁-保留多久-怎么删除" aria-label="Permalink to &quot;数据会分享给谁，保留多久，怎么删除？&quot;">​</a></h2><p>我们不会出售、出租你的个人信息，也不会为了广告而分享这些信息。你发来的邮件会经过上面说明的邮件服务商处理。如果法律要求，或你明确提出相应请求，我们可能会提供自己实际持有的信息。</p><ul><li><strong>应用内的数据：</strong> 你可以通过应用已有的删除功能或设备设置清理。要清理本地数据，请选择同时删除应用和数据的选项。保留数据的卸载或归档方式不会清空资料。备份需要单独管理，重新安装时也可能恢复其中的数据。</li><li><strong>网站偏好：</strong> 会保留在浏览器里，直到你清除此网站的数据，或浏览器自行清理。</li><li><strong>邮件和你分享的诊断信息：</strong> 只在处理问题、后续跟进或履行法律义务所需的期间保留。你可以要求删除自己发来的信息，法律要求保留的情况除外。</li><li><strong>服务商持有的数据：</strong> 例如备份和网站访问日志，由服务商按自己的规则保留和管理。</li></ul><p>如果想查看、更正或删除发给我们的信息，可以通过下方邮箱联系。只存在你设备上的记录，我们无法远程读取或删除。</p><h2 id="数据如何保护" tabindex="-1">数据如何保护？ <a class="header-anchor" href="#数据如何保护" aria-label="Permalink to &quot;数据如何保护？&quot;">​</a></h2><p>应用的本地数据使用操作系统提供的应用存储保护。本网站使用 HTTPS。我们只为处理支持和隐私请求而访问相关邮件，并使用邮件服务商提供的安全措施。</p><h2 id="儿童和未成年人的隐私" tabindex="-1">儿童和未成年人的隐私 <a class="header-anchor" href="#儿童和未成年人的隐私" aria-label="Permalink to &quot;儿童和未成年人的隐私&quot;">​</a></h2><p>使用应用不需要填写个人资料或出生日期，我们也不会有意向儿童收集个人信息。如果家长或监护人认为孩子向我们发送了个人信息，请联系我们处理删除事宜。</p><h2 id="政策更新" tabindex="-1">政策更新 <a class="header-anchor" href="#政策更新" aria-label="Permalink to &quot;政策更新&quot;">​</a></h2><p>数据处理方式有变化时，我们会更新本页和日期。重要变化会通过网站或应用更新说明告知。如果新功能需要另外申请权限或征得同意，会在相应操作时提出，不会仅凭这份政策就视为你已经同意。</p><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><p>开发者：<strong>eurekaffeine（刘耀晨）</strong><br> 应用：<strong>苍蓝星图鉴 / Sapphire Star Codex</strong><br> 邮箱：<a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',29)])])}const f=e(i,[["render",n]]);export{u as __pageData,f as default};
